#!/usr/bin/env bash
set -euo pipefail
docker compose config --quiet
docker compose up -d --build
for endpoint in 'http://localhost/' 'http://127.0.0.1/' 'http://localhost/api/hello' 'http://localhost/api/actuator/health'; do
  ok=0
  for i in $(seq 1 45); do
    if body=$(curl --fail --silent --show-error "$endpoint" 2>/dev/null); then
      case "$endpoint" in
        */api/hello) expected='Hello from forger' ;;
        */api/actuator/health) expected='"status":"UP"' ;;
        *) expected='Generated by forger' ;;
      esac
      if [[ "$body" == *"$expected"* ]]; then ok=1; break; fi
    fi
    sleep 3
  done
  if (( ! ok )); then echo "FAIL $endpoint" >&2; exit 1; fi
  echo "PASS $endpoint"
done
